   }\n\n    .toggle-switch:disabled+.toggle-switch-label,\n    .toggle-switch:disabled+.toggle-switch-label:before {\n        cursor: not-allowed;\n    }\n}\n\n.command-button {\n    flex: 1 1 0;\n\n    margin: 3px;\n    border: 0px;\n\n    min-width: 75px;\n    min-height: 40px;\n    max-height: 60px;\n\n    color: #999999;\n\n    border-bottom: 2px solid #1C9063;\n    background: linear-gradient(#000000, #111F1D);\n\n    outline: none;\n    cursor: pointer;\n\n    &:hover {\n        color: #FFFFFF;\n        background: #151E1B;\n    }\n\n    &:active {\n        background: rgba(35, 51, 45, 0.6);\n    }\n\n    &:disabled {\n        color: #999999;\n        border-color: #555555;\n        background: linear-gradient(rgba(0, 0, 0, 0.8), rgba(9, 17, 16, 0.8));\n        cursor: not-allowed\n    }\n}","@import \"media-queries\";\n@import \"common\";\n\n$min-main-view-width: 600;\n$side-bar-width: ('small': 80, 'large': 90);\n$header-height: ('small': 55, 'large': 60);\n\n:export {\n  MIN_MAIN_VIEW_WIDTH: $min-main-view-width;\n  SIDE_BAR_WIDTH_SMALL: #{map-get($side-bar-width, 'small')};\n  SIDE_BAR_WIDTH_LARGE: #{map-get($side-bar-width, 'large')};\n  HEADER_HEIGHT_SMALL: #{map-get($header-height, 'small')};\n  HEADER_HEIGHT_LARGE: #{map-get($header-height, 'large')};\n}\n\n@mixin monitor-item-common-properties($text-width: calc(100% - 17px)) {\n  display: flex;\n  list-style-type: none;\n  flex-direction: row;\n  flex-wrap: nowrap;\n  justify-content: flex-start;\n  align-items: center;\n\n  border-top: 1px solid #333333;\n  padding: 10px;\n  cursor: default;\n\n  .icon {\n    position: relative;\n    height: 20px;\n    width: 20px;\n    padding-right: 5px;\n\n    @include small-screen {\n      height: 15px;\n      width: 15px;\n    }\n  }\n\n  .text {\n    position: relative;\n    width: $text-width;\n    padding-left: 5px;\n\n    line-height: 150%;\n    font-size: 14px;\n    word-wrap: break-word;\n    white-space: pre-wrap;\n\n    @include small-screen {\n      font-size: 12px;\n    }\n  }\n\n  .time {\n    position: absolute;\n    right: 5px;\n\n    font-size: 12px;\n  }\n\n  .alert {\n    color: #D7466F;\n  }\n\n  .warn {\n    color: #A3842D;\n  }\n}\n\nbody {\n  margin: 0px;\n  overflow: hidden;\n\n  background-color: #14171A !important;\n  font: 14px \"Lucida Grande\", Helvetica, Arial, sans-serif;\n  color: #FFFFFF;\n\n  * {\n    font-size: 16px;\n\n    @include small-screen {\n      font-size: 14px;\n    }\n  }\n}\n\n.no-data {\n  padding: 20px;\n  color: #B43131;\n}\n\n\n/* Adjust the scrollbar style. */\n\n::-webkit-scrollbar {\n  width: 4px;\n  height: 8px;\n  opacity: 0.3;\n  background-color: #FFFFFF;\n}\n\n::-webkit-scrollbar-track {\n  -webkit-box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.3);\n  background-color: #555555;\n}\n\n::-webkit-scrollbar-thumb {\n  opacity: 0.8;\n  background-color: #30A5FF;\n}\n\n::-webkit-scrollbar-thumb:active {\n  background-color: #30A5FF;\n}\n\n.header {\n  display: flex;\n  align-items: center;\n\n  z-index: 100;\n  position: relative;\n  top: 0;\n  left: 0;\n  height: map-get($header-height, 'large') + 0px;\n\n  background: #000000;\n  color: #ffffff;\n  text-align: left;\n\n  @include small-screen {\n    height: map-get($header-height, 'small') + 0px;\n  }\n\n  /* The Apollo logo on the header. */\n  .apollo-logo {\n    flex: 0 0 auto;\n\n    top: 40px;\n    left: 40px;\n    height: 40px;\n    width: 121px;\n    margin: 10px auto 5px 18px;\n\n    @include small-screen {\n      top: 15px;\n      left: 25px;\n      height: 25px;\n      width: 80px;\n      margin-top: 5px;\n    }\n  }\n\n  .header-item {\n    flex: 0 0 auto;\n\n    position: relative;\n    margin: 5px;\n    border: 1px solid #383838;\n  }\n\n  .selector {\n    &.scenario-set-selector {\n      max-width: 200px;\n      overflow: hidden;\n      text-overflow: ellipsis;\n      white-space: nowrap;\n    }\n\n    select {\n      display: block;\n\n      border: none;\n      padding: 0.5em 3em 0.5em 0.5em;\n\n      background: #000000;\n      color: #ffffff;\n      outline: none;\n      cursor: pointer;\n\n      /* remove default arrow */\n      -webkit-appearance: none;\n      -moz-appearance: none;\n      appearance: none;\n    }\n\n    .arrow {\n      position: absolute;\n      top: 0px;\n      right: 0px;\n      width: 30px;\n      height: 100%;\n      border-left: 1px solid #383838;\n\n      background: #181818;\n      pointer-events: none;\n    }\n\n    .arrow:before {\n      position: absolute;\n      top: 55%;\n      right: 7px;\n      margin-top: -5px;\n      border-top: 8px solid #666666;\n      border-left: 8px solid transparent;\n      border-right: 8px solid transparent;\n\n      content: '';\n      pointer-events: none;\n    }\n  }\n\n  .header-button {\n    min-width: 125px;\n    padding: 0.5em 0em;\n\n    background: #181818;\n    color: #ffffff;\n    text-align: center;\n    cursor: pointer;\n\n    @include small-screen {\n      min-width: 110px;\n    }\n  }\n\n  .header-button-active {\n    color: #30A5FF;\n  }\n}\n\n.pane-container {\n  position: absolute;\n  width: 100%;\n  height: calc(100% - 60px);\n\n  @include small-screen {\n    height: calc(100% - 55px);\n  }\n\n  .left-pane {\n    display: flex;\n    flex-flow: row nowrap;\n    align-items: stretch;\n\n    position: absolute;\n    bottom: 0px;\n    top: 0px;\n    width: 100%;\n\n    .dreamview-body {\n      display: flex;\n      flex-flow: column nowrap;\n      flex: 1 1 auto;\n      overflow: hidden;\n      background-color: #1D2226;\n\n      .main-view {\n        flex: 0 0 auto;\n        position: relative;\n        min-width: $min-main-view-width + 0px;\n\n        #camera-image {\n          width: 100%;\n        }\n      }\n    }\n  }\n\n  .right-pane {\n    position: absolute;\n    right: 0px;\n    width: 100%;\n    height: 100%;\n    overflow: hidden;\n\n    ::-webkit-scrollbar {\n      width: 6px;\n    }\n\n    .react-tabs {\n      @extend .custom-react-tab;\n    }\n  }\n\n  .SplitPane {\n    .Resizer {\n      background: #000000;\n      opacity: 0.2;\n      z-index: 1;\n      -moz-box-sizing: border-box;\n      -webkit-box-sizing: border-box;\n      box-sizing: border-box;\n      -moz-background-clip: padding;\n      -webkit-background-clip: padding;\n      background-clip: padding-box;\n    }\n\n    .Resizer:hover {\n      -webkit-transition: all 2s ease;\n      transition: all 2s ease;\n    }\n\n    .Resizer.vertical {\n      width: 11px;\n      margin: 0 -5px;\n      border-left: 5px solid rgba(255, 255, 255, 0);\n      border-right: 5px solid rgba(255, 255, 255, 0);\n      cursor: col-resize;\n    }\n\n    .Resizer.vertical:hover {\n      border-left: 5px solid rgba(0, 0, 0, 0.5);\n      border-right: 5px solid rgba(0, 0, 0, 0.5);\n    }\n\n    .Resizer.disabled {\n      cursor: auto;\n    }\n\n    .Resizer.disabled:hover {\n      border-color: transparent;\n    }\n  }\n}\n\n\n.offlineview {\n  display: flex;\n  flex-flow: column nowrap;\n\n  position: absolute;\n  width: 100%;\n  height: 100%;\n\n  .main-view {\n    flex: 0 0 auto;\n    position: relative;\n  }\n}\n\n\n/* This is the styles for the main canvas of the dreamview container.\n   It is applied to the major <div> of <Dreamview>. */\n\n.dreamview-canvas {\n  z-index: 1;\n  position: absolute;\n\n  .geolocation {\n    z-index: 10;\n    position: absolute;\n    bottom: 10px;\n    right: 10px;\n\n    color: white;\n  }\n\n  .default-routing-input {\n    z-index: 10;\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%, -50%);\n    background: #1D2226;\n    padding: 5px;\n\n    .name-label {\n      padding: 10px 0 10px 10px;\n    }\n\n    .start-cycle-checkbox {\n      display: inline-block;\n      padding-left: 20px;\n    }\n\n    .name-input {\n      margin: 10px;\n      min-height: 20px;\n    }\n\n    .default-routing-input-btn {\n      display: flex;\n      justify-content: center;\n      align-items: center;\n\n      .input-button {\n        min-width: 100px;\n        display: inline-block;\n        margin: 0 5px 5px 5px;\n        padding: 10px 10px;\n        border: 1px solid #383838;\n        background: #1D2226;\n        color: #FFFFFF;\n        vertical-align: middle;\n        text-align: center;\n\n        @include small-screen {\n          min-width: 125px;\n        }\n      }\n\n      .submit-button {\n        background: #000000;\n      }\n\n      .input-button:active {\n        background: #383838;\n      }\n    }\n  }\n}\n\n.hidden {\n  display: none;\n}\n\n.tools {\n  display: flex;\n  flex-flow: row nowrap;\n  align-items: stretch;\n\n  flex: 1 1 auto;\n\n  overflow: hidden;\n  border-top: 1px solid #000000;\n  background: #000000;\n\n  .card {\n    flex: 1 1 auto;\n\n    margin-right: 1px;\n    padding: 15px 10px 25px 20px;\n    background: #1D2226;\n    font: 14px \"Lucida Grande\", Helvetica, Arial, sans-serif;\n    color: #FFFFFF;\n\n    @include small-screen {\n      padding: 12px 5px 15px 12px;\n    }\n\n    .card-header {\n      width: 100%;\n      padding-bottom: 15px;\n      display: flex;\n      justify-content: space-between;\n\n      span {\n        display: inline-block;\n        width: 200px;\n        height: 100%;\n        padding: 10px 10px 10px 0px;\n        text-align: center;\n\n        font-size: 18px;\n\n        @include small-screen {\n          font-size: 16px;\n        }\n\n        &:not(.active) {\n          cursor: pointer;\n        }\n\n        &.active {\n          border-bottom: 1px solid #999999;\n        }\n      }\n\n      .card-header-btn {\n        border: none;\n        border-bottom: 1px solid #999999;\n        padding: 10px 0px 10px 0px;\n        margin-right: 10px;\n        background: #1D2226;\n        color: #FFFFFF;\n        text-align: left;\n        white-space: nowrap;\n\n        font-size: 18px;\n\n        @include small-screen {\n          font-size: 16px;\n        }\n      }\n    }\n\n    .card-content-row {\n      display: flex;\n      flex-flow: row wrap;\n      align-content: flex-start;\n\n      overflow-x: hidden;\n      overflow-y: auto;\n      height: 85%;\n\n      .cycle-input {\n        display: flex;\n        margin-left: auto;\n        justify-content: flex-start;\n        justify-content: space-between;\n\n        padding: 0px;\n        border: none;\n        background: #1D2226;\n\n        .cycle-input-item {\n          margin: 10px;\n        }\n      }\n    }\n\n    .card-content-column {\n      display: flex;\n      flex-flow: column nowrap;\n      justify-content: flex-start;\n\n      overflow-x: hidden;\n      overflow-y: auto;\n      height: 89%;\n    }\n  }\n\n  .tool-view-menu {\n    display: flex;\n    flex-flow: row nowrap;\n    align-items: stretch;\n\n    flex: 2 1 auto;\n\n    z-index: 10 !important;\n    margin-left: 1px;\n    overflow-y: hidden;\n    overflow-x: auto;\n    background: #000000;\n    color: #FFFFFF;\n    text-align: left;\n    white-space: nowrap;\n\n    .summary {\n      line-height: 50px;\n\n      @include small-screen {\n        line-height: 25px;\n      }\n\n      img {\n        position: relative;\n        width: 30px;\n        height: 30px;\n        transform: translate(-30%, 25%);\n\n        @include small-screen {\n          width: 20px;\n          height: 20px;\n          transform: translate(-50%, 10%);\n        }\n      }\n\n      span {\n        padding-left: 10px;\n      }\n    }\n\n    /*  Radio button */\n    input[type=\"radio\"] {\n      display: none;\n    }\n\n    .radio-selector-label {\n      display: inline-block;\n      position: relative;\n      transform: translate(10%, 30%);\n      box-sizing: border-box;\n      -webkit-box-sizing: border-box;\n      width: 25px;\n      height: 25px;\n      margin-right: 6px;\n      border-radius: 50%;\n      -webkit-border-radius: 50%;\n      background-color: #A0A0A0;\n      box-shadow: inset 1px 0 #A0A0A0;\n      border: 7px solid #3F4548;\n    }\n\n    input[type=\"radio\"]:checked + .radio-selector-label {\n      border: 7px solid #0E3D62;\n      background-color: #30A5FF;\n    }\n  }\n\n  .console {\n    z-index: 10;\n    position: relative;\n    min-width: 230px;\n    margin: 0px;\n    border: none;\n    padding: 0px;\n\n    overflow: hidden;\n\n    .monitor-item {\n      color: #fff;\n      @include monitor-item-common-properties(calc(100% - 82px));\n    }\n  }\n\n  .default-routing-button {\n    min-width: 360px;\n\n    @include small-screen {\n      min-width: 320px;\n    }\n  }\n}\n\n.side-bar {\n  display: flex;\n  flex-direction: column;\n\n  flex: 0 0 auto;\n\n  z-index: 100;\n  background: #1D2226;\n  border-right: 1px solid #000000;\n  overflow-y: auto;\n  overflow-x: hidden;\n\n  .main-panel {\n    margin-bottom: auto;\n  }\n\n  .button {\n    display: block;\n    width: map-get($side-bar-width, 'large') + 0px;\n    border: none;\n    padding: 20px 10px;\n\n    text-align: center;\n    background: #1D2226;\n    color: #FFFFFF;\n    opacity: 0.6;\n    cursor: pointer;\n\n    @include small-screen {\n      width: map-get($side-bar-width, 'small') + 0px;\n      padding-top: 10px;\n    }\n\n    .icon {\n      width: 40px;\n      height: 40px;\n      margin: auto;\n\n      @include small-screen {\n        width: 30px;\n        height: 30px;\n      }\n    }\n\n    .label {\n      padding-top: 10px;\n\n      @include small-screen {\n        padding-top: 4px;\n      }\n    }\n  }\n\n  .button:first-child {\n    padding-top: 25px;\n\n    @include small-screen {\n      padding-top: 10px;\n    }\n  }\n\n  .button:disabled {\n    color: #414141;\n    cursor: not-allowed;\n\n    .icon {\n      opacity: 0.2;\n    }\n  }\n\n  .button-active {\n    background: #2A3238;\n    opacity: 1;\n    color: #FFFFFF;\n  }\n\n  .sub-button {\n    display: block;\n    width: 90px;\n    height: 80px;\n    border: none;\n    padding: 10px;\n\n    text-align: center;\n    background: #3E4041;\n    color: #999999;\n    cursor: pointer;\n\n    @include small-screen {\n      width: 80px;\n      height: 60px;\n    }\n  }\n\n  .sub-button:not(:last-child) {\n    border-bottom: 1px solid #1D2226;\n  }\n\n  .sub-button:disabled {\n    cursor: not-allowed;\n    opacity: 0.3;\n  }\n\n  .sub-button-active {\n    background: #30A5FF;\n    color: #FFFFFF;\n  }\n}\n\n.status-bar {\n  z-index: 10;\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n\n  .rss {\n    flex: 1 1 auto;\n    position: absolute;\n    width: 240px;\n    height: 270px;\n    top: 10px;\n    right: 250px;\n    background: rgba(0, 0, 0, 0.8);\n\n    .rss-header {\n      width: 100%;\n      text-align: center;\n      font-size: 15px;\n\n      div {\n        padding: 5px 0 5px 0;\n      }\n    }\n\n    .rss-content-column {\n      flex-flow: column nowrap;\n      overflow-x: hidden;\n      overflow-y: auto;\n      height: 89%;\n    }\n\n    .rss-console {\n      z-index: 10;\n      position: relative;\n      min-width: 230px;\n      margin: 0px;\n      border: none;\n      padding: 0px;\n      overflow: hidden;\n      white-space: pre-wrap;\n\n      .monitor-item {\n        color: #fff;\n        @include monitor-item-common-properties(calc(100% - 80px));\n      }\n    }\n  }\n\n  .battery-and-gears {\n    position: absolute;\n    width: 224px;\n    height: 35px;\n    right: 20px;\n    background: rgba(0, 0, 0, 0.8);\n\n    font-size: 14px;\n\n    .left-div {\n      position: absolute;\n      width: 116px;\n      height: 35px;\n    }\n\n    .right-div {\n      position: absolute;\n      top: 0px;\n      right: 0px;\n      width: 105px;\n      height: 35px;\n    }\n\n    .text {\n      position: absolute;\n      top: 50%;\n      left: 50%;\n\n      float: right;\n      transform: translate(-50%, -50%);\n      text-align: center;\n      font-size: 14px;\n      color: #FFFFFF;\n    }\n  }\n\n  .electricity-status {\n    top: 287px;\n    background: rgba(0, 0, 0, 0.5);\n  }\n\n  .auto-meter {\n    position: absolute;\n    width: 224px;\n    height: 112px;\n    top: 10px;\n    right: 20px;\n    backgroun